package br.com.coleta.sistemas.solicitacoes.Consumer;
import br.com.coleta.sistemas.solicitacoes.Dto.Envelope;
import br.com.coleta.sistemas.solicitacoes.Entity.*;
import br.com.coleta.sistemas.solicitacoes.Repository.*;
import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.beans.factory.annotation.Value;
import tools.jackson.databind.ObjectMapper; import lombok.RequiredArgsConstructor; import java.util.*; import java.time.*;
@Component @RequiredArgsConstructor public class ResultadoReservaConsumer {
 private final ObjectMapper mapper; private final SolicitacaoRespository repo; private final MensagemProcessadaRepository inbox; private final OutboxEventoRepository outbox;
 @Value("${SAGA_TIMEOUT_SECONDS:15}") private long timeout;
 private void emitir(Solicitacao s,String rota,String tipo,Map<String,Object> p){outbox.save(new OutboxEvento(s.getId(),rota,mapper.writeValueAsString(Envelope.criar(s.getId(),tipo,p))));}
 private void compensar(Solicitacao s){s.cancelar(); emitir(s,"agenda.liberar-reserva","LiberarReserva",Map.of("solicitacaoId",s.getId())); emitir(s,"cooperativa.cancelar-compromisso","CancelarCompromisso",Map.of("solicitacaoId",s.getId(),"motivoCancelamento","Saga cancelada"));}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_RESULTADO:solicitacoes.resultado}") @Transactional public void receber(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"ResultadoReserva");var e=mapper.readValue(body,Envelope.class);e.validar("ResultadoReserva");var s=repo.buscarPorIdComBloqueio(e.id("solicitacaoId")).orElseThrow(); if(!(e.payload().get("reservada") instanceof Boolean))throw new IllegalArgumentException("reservada"); if(!inbox.registrarSeNovo(e.messageId().toString(),e.type()))return;
 if(s.getStatus()==StatusSolicitacao.CANCELADA){if(Boolean.TRUE.equals(e.payload().get("reservada")))compensar(s);return;} if(s.getStatus()!=StatusSolicitacao.PENDENTE&&s.getStatus()!=StatusSolicitacao.AGUARDANDO_RESERVA)return;
 if(!Boolean.TRUE.equals(e.payload().get("reservada"))){s.cancelar();return;} s.reservar(e.id("reservaId"),Instant.now().plusSeconds(timeout)); emitir(s,"cooperativa.solicitar-aceite","SolicitarAceiteCooperativa",Map.of("solicitacaoId",s.getId(),"reservaId",s.getReservaId(),"categoriaResiduo","ELETRONICO","quantidadeEstimada",1,"dataAgendada",s.getDataColeta().atStartOfDay(ZoneOffset.UTC).toInstant()));}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_ACEITE:solicitacoes.aceite}") @Transactional public void aceite(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"CooperativaAceitou");var e=mapper.readValue(body,Envelope.class);e.validar("CooperativaAceitou");var s=repo.buscarPorIdComBloqueio(e.id("solicitacaoId")).orElseThrow();if(!inbox.registrarSeNovo(e.messageId().toString(),e.type()))return;if(s.getStatus()==StatusSolicitacao.CONFIRMADA)return;if(s.getStatus()!=StatusSolicitacao.AGUARDANDO_COOPERATIVA||!Instant.now().isBefore(s.getPrazo())){compensar(s);return;}if(!s.getReservaId().equals(e.id("reservaId")))throw new IllegalArgumentException("reserva divergente");s.confirmar();emitir(s,"coleta.confirmada","ColetaConfirmada",Map.of("solicitacaoId",s.getId(),"reservaId",s.getReservaId(),"compromissoId",e.id("compromissoId")));}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_RECUSA:solicitacoes.recusa}") @Transactional public void recusa(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"CooperativaRecusou");var e=mapper.readValue(body,Envelope.class);e.validar("CooperativaRecusou");var s=repo.buscarPorIdComBloqueio(e.id("solicitacaoId")).orElseThrow();if(inbox.registrarSeNovo(e.messageId().toString(),e.type())&&s.getStatus()==StatusSolicitacao.AGUARDANDO_COOPERATIVA)compensar(s);}
 @Scheduled(fixedDelay=1000) @Transactional public void expirar(){for(var id:repo.expiradas(Instant.now())){var s=repo.buscarPorIdComBloqueio(id).orElseThrow();if(s.getStatus()==StatusSolicitacao.AGUARDANDO_COOPERATIVA&&!Instant.now().isBefore(s.getPrazo()))compensar(s);}}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_CANCELADO:solicitacoes.cancelado}") @Transactional public void cancelado(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"CompromissoCancelado");var e=mapper.readValue(body,Envelope.class);e.validar("CompromissoCancelado");inbox.registrarSeNovo(e.messageId().toString(),e.type());}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_EXECUTADA:solicitacoes.executada}") @Transactional public void executada(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"ColetaExecutada");var e=mapper.readValue(body,Envelope.class);e.validar("ColetaExecutada");inbox.registrarSeNovo(e.messageId().toString(),e.type());}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_TRIADA:solicitacoes.triada}") @Transactional public void triada(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"ColetaTriada");var e=mapper.readValue(body,Envelope.class);e.validar("ColetaTriada");inbox.registrarSeNovo(e.messageId().toString(),e.type());}
 @RabbitListener(queues="${MQ_QUEUE_SOLICITACOES_DESTINADA:solicitacoes.destinada}") @Transactional public void destinada(String body){br.com.coleta.sistemas.solicitacoes.ContratoEvento.validar(mapper,body,"ColetaDestinada");var e=mapper.readValue(body,Envelope.class);e.validar("ColetaDestinada");inbox.registrarSeNovo(e.messageId().toString(),e.type());}
}
